package com.example.memory;

import android.os.Bundle;
import android.os.Handler;
import android.widget.ImageButton;
import android.widget.ImageView;

import androidx.activity.EdgeToEdge;
import androidx.appcompat.app.AppCompatActivity;
import androidx.core.graphics.Insets;
import androidx.core.view.ViewCompat;
import androidx.core.view.WindowInsetsCompat;

import java.util.ArrayList;
import java.util.Collections;

public class MainActivity extends AppCompatActivity {

 ImageView imb00, imb01, imb02, imb03, imb04, imb05, imb06, imb07, imb08, imb09, imb10, imb11, imb12, imb13, imb14, imb15;
 ImageView [] tauler = new ImageView [16];
 int[] img;
 int fons;

 ArrayList<Integer> arrayDesordre;
 ImageView primer;
 int numPrimer, numSegon;
 boolean bloc = false;
 final Handler handler = new Handler();

 @Override
 protected void onCreate(Bundle savedInstanceState) {
 super.onCreate(savedInstanceState);
 EdgeToEdge.enable(this);
 setContentView(R.layout.activity_main);
 ViewCompat.setOnApplyWindowInsetsListener(findViewById(R.id.main), (v, insets) -> {
 Insets systemBars = insets.getInsets(WindowInsetsCompat.Type.systemBars());
 v.setPadding(systemBars.left, systemBars.top, systemBars.right, systemBars.bottom);
 return insets;


 });

 init();
 }

 private void caregarTauler(){
 imb00 = findViewById(R.id.imb00);
 imb01 = findViewById(R.id.imb01);
 imb02 = findViewById(R.id.imb02);
 imb03 = findViewById(R.id.imb03);
 imb04 = findViewById(R.id.imb04);
 imb05 = findViewById(R.id.imb05);
 imb06 = findViewById(R.id.imb06);
 imb07 = findViewById(R.id.imb07);
 imb08 = findViewById(R.id.imb08);
 imb09 = findViewById(R.id.imb09);
 imb10 = findViewById(R.id.imb10);
 imb11 = findViewById(R.id.imb11);
 imb12 = findViewById(R.id.imb12);
 imb13 = findViewById(R.id.imb13);
 imb14 = findViewById(R.id.imb14);
 imb15 = findViewById(R.id.imb15);

 tauler[0] = imb00;
 tauler[1] = imb01;
 tauler[2] = imb02;
 tauler[3] = imb03;
 tauler[4] = imb04;
 tauler[5] = imb05;
 tauler[6] = imb06;
 tauler[7] = imb07;
 tauler[8] = imb08;
 tauler[9] = imb09;
 tauler[10] = imb10;
 tauler[11] = imb11;
 tauler[12] = imb12;
 tauler[13] = imb13;
 tauler[14] = imb14;
 tauler[15] = imb15;
 }

 private void carregarImg(){

 img = new int[]{
 R.drawable.la0,
 R.drawable.la1,
 R.drawable.la2,
 R.drawable.la3,
 R.drawable.la4,
 R.drawable.la5,
 R.drawable.la6,
 R.drawable.la7
 };
 fons = R.drawable.fondo;
 }

 private ArrayList<Integer> mesclar(int longitud){
 ArrayList<Integer> result = new ArrayList<>();
 for (int i = 0; i<longitud; i++){
 result.add(i% longitud);
 }
 Collections.shuffle(result);
 return result;
 }

 private void comprobar(int i, final ImageView imgb){
 if (primer == null){
 primer = imgb;
 primer.setScaleType(ImageView.ScaleType.CENTER_CROP);
 primer.setImageResource(img[arrayDesordre.get(i)]);
 primer.setEnabled(false);
 numPrimer = arrayDesordre.get(i);

 }else {
 bloc = true;
 imgb.setScaleType(ImageView.ScaleType.CENTER_CROP);
 imgb.setImageResource(img[arrayDesordre.get(i)]);
 imgb.setEnabled(false);
 numSegon = arrayDesordre.get(i);
 if (numPrimer == numSegon){
 primer = null;
 bloc = false;
 //si es igual sumes punts
 } else {
 handler.postDelayed(()-> {
 primer.setScaleType((ImageView.ScaleType.CENTER_CROP));
 primer.setImageResource(fons);
 primer.setEnabled(false);

 imgb.setScaleType((ImageView.ScaleType.CENTER_CROP));
 imgb.setImageResource(fons);
 imgb.setEnabled(false);

 bloc = false;
 primer = null;
 //si em fallat resta punts
 }, 1000);

 }
 }
 }

 private void init() {

 caregarTauler();
 carregarImg();
 arrayDesordre = mesclar(img.length);
 for (int i = 0; i < tauler.length; i++) {
 tauler[i].setScaleType(ImageView.ScaleType.CENTER_CROP);
 tauler[i].setImageResource(img[arrayDesordre.get(i)]);
 }
 handler.postDelayed(() -> {
 for (int i = 0; i < tauler.length; i++) {
 tauler[i].setScaleType(ImageView.ScaleType.CENTER_CROP);
 tauler[i].setImageResource(fons);
 }

 }, 500);
 for (int i = 0; i < tauler.length; i++) {
 final int j = i;
 tauler[i].setEnabled(true);
 tauler[i].setOnClickListener((v)->{
 if(!bloc)
 comprobar(j, tauler[j]);
 });
 }
 }

