import android.os.Bundle
import android.os.Handler
import android.os.Looper
import android.widget.ImageView
import androidx.activity.enableEdgeToEdge
import androidx.appcompat.app.AppCompatActivity
import androidx.core.view.ViewCompat
import androidx.core.view.WindowInsetsCompat

class MemoryScreen : AppCompatActivity() {

 private lateinit var imb00: ImageView
 private lateinit var imb01: ImageView
 private lateinit var imb02: ImageView
 private lateinit var imb03: ImageView
 private lateinit var imb04: ImageView
 private lateinit var imb05: ImageView
 private lateinit var imb06: ImageView
 private lateinit var imb07: ImageView
 private lateinit var imb08: ImageView
 private lateinit var imb09: ImageView
 private lateinit var imb10: ImageView
 private lateinit var imb11: ImageView
 private lateinit var imb12: ImageView
 private lateinit var imb13: ImageView
 private lateinit var imb14: ImageView
 private lateinit var imb15: ImageView
 
 private lateinit var tauler: Array<ImageView>
 private lateinit var img: IntArray
 private var fons: Int = 0

 private lateinit var arrayDesordre: ArrayList<Int>
 private var primer: ImageView? = null
 private var numPrimer: Int = 0
 private var numSegon: Int = 0
 private var bloc: Boolean = false
 private val handler = Handler(Looper.getMainLooper())

 override fun onCreate(savedInstanceState: Bundle?) {
 super.onCreate(savedInstanceState)
 enableEdgeToEdge()
 setContentView(R.layout.activity_main)
 
 ViewCompat.setOnApplyWindowInsetsListener(findViewById(R.id.main)) { v, insets ->
 val systemBars = insets.getInsets(WindowInsetsCompat.Type.systemBars())
 v.setPadding(systemBars.left, systemBars.top, systemBars.right, systemBars.bottom)
 insets
 }

 init()
 }

 private fun caregarTauler() {
 imb00 = findViewById(R.id.imb00)
 imb01 = findViewById(R.id.imb01)
 imb02 = findViewById(R.id.imb02)
 imb03 = findViewById(R.id.imb03)
 imb04 = findViewById(R.id.imb04)
 imb05 = findViewById(R.id.imb05)
 imb06 = findViewById(R.id.imb06)
 imb07 = findViewById(R.id.imb07)
 imb08 = findViewById(R.id.imb08)
 imb09 = findViewById(R.id.imb09)
 imb10 = findViewById(R.id.imb10)
 imb11 = findViewById(R.id.imb11)
 imb12 = findViewById(R.id.imb12)
 imb13 = findViewById(R.id.imb13)
 imb14 = findViewById(R.id.imb14)
 imb15 = findViewById(R.id.imb15)

 tauler = arrayOf(
 imb00, imb01, imb02, imb03,
 imb04, imb05, imb06, imb07,
 imb08, imb09, imb10, imb11,
 imb12, imb13, imb14, imb15
 )
 }

 private fun carregarImg() {
 img = intArrayOf(
 R.drawable.la0,
 R.drawable.la1,
 R.drawable.la2,
 R.drawable.la3,
 R.drawable.la4,
 R.drawable.la5,
 R.drawable.la6,
 R.drawable.la7
 )
 fons = R.drawable.fondo
 }

 private fun mesclar(longitud: Int): ArrayList<Int> {
 val result = ArrayList<Int>()
 for (i in 0 until longitud) {
 result.add(i % longitud)
 }
 result.shuffle()
 return result
 }

 private fun comprobar(i: Int, imgb: ImageView) {
 if (primer == null) {
 primer = imgb
 primer?.scaleType = ImageView.ScaleType.CENTER_CROP
 primer?.setImageResource(img[arrayDesordre[i]])
 primer?.isEnabled = false
 numPrimer = arrayDesordre[i]
 } else {
 bloc = true
 imgb.scaleType = ImageView.ScaleType.CENTER_CROP
 imgb.setImageResource(img[arrayDesordre[i]])
 imgb.isEnabled = false
 numSegon = arrayDesordre[i]
 
 if (numPrimer == numSegon) {
 primer = null
 bloc = false
 // si es igual sumes punts
 } else {
 handler.postDelayed({
 primer?.scaleType = ImageView.ScaleType.CENTER_CROP
 primer?.setImageResource(fons)
 primer?.isEnabled = true

 imgb.scaleType = ImageView.ScaleType.CENTER_CROP
 imgb.setImageResource(fons)
 imgb.isEnabled = true

 bloc = false
 primer = null
 // si em fallat resta punts
 }, 1000)
 }
 }
 }

 private fun init() {
 caregarTauler()
 carregarImg()
 arrayDesordre = mesclar(img.size)
 
 for (i in tauler.indices) {
 tauler[i].scaleType = ImageView.ScaleType.CENTER_CROP
 tauler[i].setImageResource(img[arrayDesordre[i]])
 }
 
 handler.postDelayed({
 for (i in tauler.indices) {
 tauler[i].scaleType = ImageView.ScaleType.CENTER_CROP
 tauler[i].setImageResource(fons)
 }
 }, 500)
 
 for (i in tauler.indices) {
 tauler[i].isEnabled = true
 tauler[i].setOnClickListener {
 if (!bloc) {
 comprobar(i, tauler[i])
 }
 }
 }
 }
}
