 18|@Composable
 19|fun MemoryScreen() {
 20| // Coroutine scope for async operations
 21| val coroutineScope = rememberCoroutineScope()
 22| 
 23| // State variables
 24| var tauler by remember { mutableStateOf(List(16) { 0 }) }
 25| var visibleCards by remember { mutableStateOf(List(16) { false }) }
 26| var matchedCards by remember { mutableStateOf(List(16) { false }) }
 27| var primer by remember { mutableStateOf<Int?>(null) }
 28| var numPrimer by remember { mutableStateOf(0) }
 29| var bloc by remember { mutableStateOf(false) }
 30| var showInitialCards by remember { mutableStateOf(true) }
 31|
 32| // Image resources (you'll need to replace these with your actual drawable resources)
 33| val img = remember {
 34| intArrayOf(
 35| R.drawable.la0,
 36| R.drawable.la1,
 37| R.drawable.la2,
 38| R.drawable.la3,
 39| R.drawable.la4,
 40| R.drawable.la5,
 41| R.drawable.la6,
 42| R.drawable.la7
 43| )
 44| }
 45| val fons = R.drawable.fondo
 46|
 47| // Initialize the game
 48| LaunchedEffect(Unit) {
 49| // Shuffle and create pairs
 50| val arrayDesordre = mesclar(img.size)
 51| tauler = arrayDesordre
 52| 
 53| // Show all cards initially
 54| visibleCards = List(16) { true }
 55| delay(500)
 56| 
 57| // Hide all cards after delay
 58| visibleCards = List(16) { false }
 59| showInitialCards = false
 60| }
 61|
 62| // Game grid
 63| LazyVerticalGrid(
 64| columns = GridCells.Fixed(4),
 65| modifier = Modifier
 66| .fillMaxSize()
 67| .padding(16.dp),
 68| horizontalArrangement = Arrangement.spacedBy(8.dp),
 69| verticalArrangement = Arrangement.spacedBy(8.dp)
 70| ) {
 71| itemsIndexed(tauler) { index, cardValue ->
 72| MemoryCard(
 73| cardValue = cardValue,
 74| isVisible = visibleCards[index] || matchedCards[index],
 75| isMatched = matchedCards[index],
 76| img = img,
 77| fons = fons,
 78| enabled = !bloc && !showInitialCards && !matchedCards[index],
 79| onClick = {
 80| if (!bloc && !visibleCards[index] && !matchedCards[index]) {
 81| if (primer == null) {
 82| // First card clicked
 83| primer = index
 84| numPrimer = tauler[index]
 85| visibleCards = visibleCards.toMutableList().apply { set(index, true) }
 86| } else {
 87| // Second card clicked
 88| bloc = true
 89| val numSegon = tauler[index]
 90| visibleCards = visibleCards.toMutableList().apply { set(index, true) }
 91|
 92| if (numPrimer == numSegon) {
 93| // Match found
 94| matchedCards = matchedCards.toMutableList().apply {
 95| set(primer!!, true)
 96| set(index, true)
 97| }
 98| primer = null
 99| bloc = false
100| // si es igual sumes punts
101| } else {
102| // No match
103| // si em fallat resta punts
104| val primerIndex = primer!!
105| coroutineScope.launch {
106| delay(1000)
107| visibleCards = visibleCards.toMutableList().apply {
108| set(primerIndex, false)
109| set(index, false)
110| }
111| primer = null
112| bloc = false
113| }
114| }
115| }
116| }
117| }
118| )
119| }
120| }
121|}
122|
123|@Composable
124|fun MemoryCard(
125| cardValue: Int,
126| isVisible: Boolean,
127| isMatched: Boolean,
128| img: IntArray,
129| fons: Int,
130| enabled: Boolean,
131| onClick: () -> Unit
132|) {
133| val imageResource = if (isVisible || isMatched) img[cardValue] else fons
134| 
135| Image(
136| painter = painterResource(id = imageResource),
137| contentDescription = "Memory card",
138| modifier = Modifier
139| .aspectRatio(1f)
140| .clickable(enabled = enabled) { onClick() },
141| contentScale = ContentScale.Crop
142| )
143|}
144|
145|private fun mesclar(longitud: Int): List<Int> {
146| val result = mutableListOf<Int>()
147| for (i in 0 until longitud) {
148| result.add(i % longitud)
149| }
150| return result.shuffled()
151|}
