349|fun aiMove(board: List<CellState>): List<CellState> {
350| val emptyIndices = board.indices.filter { board[it] == CellState.EMPTY }
351|
352| if (emptyIndices.isEmpty()) {
353| return board
354| }
355|
356| val randomIndex = emptyIndices[Random.nextInt(emptyIndices.size)]
357| return board.toMutableList().apply { this[randomIndex] = CellState.X }
358|}
