 26|@Composable
 27|fun MemoryScreen(onNavigateBack: () -> Unit = {}) {
 28| // Coroutine scope for async operations
 29| val coroutineScope = rememberCoroutineScope()
 30| 
 31| // State variables
 32| var tauler by remember { mutableStateOf(List(16) { 0 }) }
 33| var visibleCards by remember { mutableStateOf(List(16) { false }) }
 34| var matchedCards by remember { mutableStateOf(List(16) { false }) }
 35| var primer by remember { mutableStateOf<Int?>(null) }
 36| var numPrimer by remember { mutableStateOf(0) }
 37| var bloc by remember { mutableStateOf(false) }
 38| var showInitialCards by remember { mutableStateOf(true) }
 39|
 40| // Image resources (you'll need to replace these with your actual drawable resources)
 41| val img = remember {
 42| intArrayOf(
 43| R.drawable.la0,
 44| R.drawable.la1,
 45| R.drawable.la2,
 46| R.drawable.la3,
 47| R.drawable.la4,
 48| R.drawable.la5,
 49| R.drawable.la6,
 50| R.drawable.la7
 51| )
 52| }
 53| val fons = R.drawable.fondo
 54|
 55| // Initialize the game
 56| LaunchedEffect(Unit) {
 57| // Shuffle and create pairs
 58| val arrayDesordre = mesclar(img.size)
 59| tauler = arrayDesordre
 60| 
 61| // Show all cards initially
 62| visibleCards = List(16) { true }
 63| delay(500)
 64| 
 65| // Hide all cards after delay
 66| visibleCards = List(16) { false }
 67| showInitialCards = false
 68| }
 69|
 70| Box(modifier = Modifier.fillMaxSize()) {
 71| // Game grid
 72| LazyVerticalGrid(
 73| columns = GridCells.Fixed(4),
 74| modifier = Modifier
 75| .fillMaxSize()
 76| .padding(16.dp)
 77| .padding(bottom = 80.dp),
 78| horizontalArrangement = Arrangement.spacedBy(8.dp),
 79| verticalArrangement = Arrangement.spacedBy(8.dp)
 80| ) {
 81| itemsIndexed(tauler) { index, cardValue ->
 82| MemoryCard(
 83| cardValue = cardValue,
 84| isVisible = visibleCards[index] || matchedCards[index],
 85| isMatched = matchedCards[index],
 86| img = img,
 87| fons = fons,
 88| enabled = !bloc && !showInitialCards && !matchedCards[index],
 89| onClick = {
 90| if (!bloc && !visibleCards[index] && !matchedCards[index]) {
 91| if (primer == null) {
 92| // First card clicked
 93| primer = index
 94| numPrimer = tauler[index]
 95| visibleCards = visibleCards.toMutableList().apply { set(index, true) }
 96| } else {
 97| // Second card clicked
 98| bloc = true
 99| val numSegon = tauler[index]
100| visibleCards = visibleCards.toMutableList().apply { set(index, true) }
101|
102| if (numPrimer == numSegon) {
103| // Match found
104| matchedCards = matchedCards.toMutableList().apply {
105| set(primer!!, true)
106| set(index, true)
107| }
108| primer = null
109| bloc = false
110| // si es igual sumes punts
111| } else {
112| // No match
113| // si em fallat resta punts
114| val primerIndex = primer!!
115| coroutineScope.launch {
116| delay(1000)
117| visibleCards = visibleCards.toMutableList().apply {
118| set(primerIndex, false)
119| set(index, false)
120| }
121| primer = null
122| bloc = false
123| }
124| }
125| }
126| }
127| }
128| )
129| }
130| }
131|
132| // Back button at the bottom
133| Box(
134| modifier = Modifier
135| .fillMaxSize()
136| .padding(bottom = 16.dp, start = 16.dp, end = 16.dp),
137| contentAlignment = Alignment.BottomCenter
138| ) {
139| Button(
140| onClick = onNavigateBack,
141| colors = ButtonDefaults.buttonColors(
142| containerColor = Color(0xFF607D8B)
143| ),
144| shape = RoundedCornerShape(8.dp),
145| modifier = Modifier.fillMaxWidth()
146| ) {
147| Text(
148| text = "← Tornar al Menú",
149| fontSize = 18.sp,
150| fontWeight = FontWeight.Bold,
151| modifier = Modifier.padding(horizontal = 16.dp, vertical = 4.dp)
152| )
153| }
154| }
155| }
