158|@Composable
159|fun MemoryCard(
160| cardValue: Int,
161| isVisible: Boolean,
162| isMatched: Boolean,
163| img: IntArray,
164| fons: Int,
165| enabled: Boolean,
166| onClick: () -> Unit
167|) {
168| val imageResource = if (isVisible || isMatched) img[cardValue] else fons
169| 
170| Image(
171| painter = painterResource(id = imageResource),
172| contentDescription = "Memory card",
173| modifier = Modifier
174| .aspectRatio(1f)
175| .clickable(enabled = enabled) { onClick() },
176| contentScale = ContentScale.Crop
177| )
178|}
179|
180|private fun mesclar(longitud: Int): List<Int> {
181| val result = mutableListOf<Int>()
182| // Add each image twice (8 images x 2 = 16 cards)
183| for (i in 0 until longitud) {
184| result.add(i)
185| result.add(i)
186| }
187| return result.shuffled()
188|}
