 45|@Composable
 46|fun TresEnRatllaScreen(onNavigateBack: () -> Unit = {}) {
 47| var board by remember { mutableStateOf(List(9) { CellState.EMPTY }) }
 48| var gameOver by remember { mutableStateOf(false) }
 49| var winner by remember { mutableStateOf<CellState?>(null) }
 50| var aiShouldMove by remember { mutableStateOf(false) }
 51|
 52| // Marcador
 53| var wins by remember { mutableStateOf(0) }
 54| var losses by remember { mutableStateOf(0) }
 55| var ties by remember { mutableStateOf(0) }
 56|
 57| // Check for winner after each move
 58| fun checkWinner(): CellState? {
 59| val winPatterns = listOf(
 60| listOf(0, 1, 2), listOf(3, 4, 5), listOf(6, 7, 8), // Rows
 61| listOf(0, 3, 6), listOf(1, 4, 7), listOf(2, 5, 8), // Columns
 62| listOf(0, 4, 8), listOf(2, 4, 6) // Diagonals
 63| )
 64|
 65| for (pattern in winPatterns) {
 66| val (a, b, c) = pattern
 67| if (board[a] != CellState.EMPTY &&
 68| board[a] == board[b] &&
 69| board[b] == board[c]
 70| ) {
 71| return board[a]
 72| }
 73| }
 74|
 75| if (board.none { it == CellState.EMPTY }) {
 76| return CellState.EMPTY
 77| }
 78|
 79| return null
 80| }
 81|
 82| fun handlePlayerMove(index: Int) {
 83| if (board[index] == CellState.EMPTY && !gameOver && !aiShouldMove) {
 84| board = board.toMutableList().apply { this[index] = CellState.O }
 85|
 86| val result = checkWinner()
 87| if (result != null) {
 88| gameOver = true
 89| winner = result
 90| // Actualitzar marcador
 91| when (result) {
 92| CellState.O -> wins++
 93| CellState.X -> losses++
 94| else -> ties++
 95| }
 96| } else {
 97| aiShouldMove = true
 98| }
 99| }
100| }
101|
102| LaunchedEffect(aiShouldMove) {
103| if (aiShouldMove) {
104| delay(200) // 0.2 second delay
105| board = aiMove(board)
106| val aiResult = checkWinner()
107| if (aiResult != null) {
108| gameOver = true
109| winner = aiResult
110| // Actualitzar marcador
111| when (aiResult) {
112| CellState.O -> wins++
113| CellState.X -> losses++
114| else -> ties++
115| }
116| }
117| aiShouldMove = false
118| }
119| }
