 2|
 3|import androidx.compose.foundation.Image
 4|import androidx.compose.foundation.clickable
 5|import androidx.compose.foundation.layout.*
 6|import androidx.compose.foundation.lazy.grid.GridCells
 7|import androidx.compose.foundation.lazy.grid.LazyVerticalGrid
 8|import androidx.compose.foundation.lazy.grid.itemsIndexed
 9|import androidx.compose.foundation.shape.RoundedCornerShape
 10|import androidx.compose.material3.Button
 11|import androidx.compose.material3.ButtonDefaults
 12|import androidx.compose.material3.Text
 13|import androidx.compose.runtime.*
 14|import androidx.compose.ui.Alignment
 15|import androidx.compose.ui.Modifier
 16|import androidx.compose.ui.graphics.Color
 17|import androidx.compose.ui.layout.ContentScale
 18|import androidx.compose.ui.res.painterResource
 19|import androidx.compose.ui.text.font.FontWeight
 20|import androidx.compose.ui.tooling.preview.Preview
 21|import androidx.compose.ui.unit.dp
 22|import androidx.compose.ui.unit.sp
 23|import kotlinx.coroutines.delay
 24|import kotlinx.coroutines.launch
 25|
 26|@Composable
 27|fun MemoryScreen(onNavigateBack: () -> Unit = {}) {
 28| // Coroutine scope for async operations
 29| val coroutineScope = rememberCoroutineScope()
 30| 
 31| // State variables
 32| var tauler by remember { mutableStateOf(List(16) { 0 }) }
 33| var visibleCards by remember { mutableStateOf(List(16) { false }) }
 34| var matchedCards by remember { mutableStateOf(List(16) { false }) }
 35| var primer by remember { mutableStateOf<Int?>(null) }
 36| var numPrimer by remember { mutableStateOf(0) }
 37| var bloc by remember { mutableStateOf(false) }
 38| var showInitialCards by remember { mutableStateOf(true) }
 39| var puntuacio by remember { mutableStateOf(0) }
 40| var intents by remember { mutableStateOf(0) }
 41|
 42| // Image resources (you'll need to replace these with your actual drawable resources)
 43| val img = remember {
 44| intArrayOf(
 45| R.drawable.la0,
 46| R.drawable.la1,
 47| R.drawable.la2,
 48| R.drawable.la3,
 49| R.drawable.la4,
 50| R.drawable.la5,
 51| R.drawable.la6,
 52| R.drawable.la7
 53| )
 54| }
 55| val fons = R.drawable.fondo
 56|
 57| // Function to initialize/restart the game
 58| fun iniciarPartida() {
 59| coroutineScope.launch {
 60| // Block interaction first and hide everything
 61| showInitialCards = true
 62| visibleCards = List(16) { false }
 63| matchedCards = List(16) { false }
 64| 
 65| // Small delay to ensure UI updates
 66| delay(50)
 67| 
 68| // Reset all game state
 69| val arrayDesordre = mesclar(img.size)
 70| tauler = arrayDesordre
 71| primer = null
 72| numPrimer = 0
 73| bloc = false
 74| puntuacio = 0
 75| intents = 0
 76| 
 77| // Show all cards initially for preview
 78| visibleCards = List(16) { true }
 79| delay(1500)
 80| 
 81| // Hide all cards after delay
 82| visibleCards = List(16) { false }
 83| showInitialCards = false
 84| }
 85| }
 86|
 87| // Initialize the game on first load
 88| LaunchedEffect(Unit) {
 89| iniciarPartida()
 90| }
 91|
 92| Box(modifier = Modifier.fillMaxSize()) {
 93| Column(modifier = Modifier.fillMaxSize()) {
 94| // Score and restart section at the top
 95| Row(
 96| modifier = Modifier
 97| .fillMaxWidth()
 98| .padding(16.dp),
 99| horizontalArrangement = Arrangement.SpaceBetween,
100| verticalAlignment = Alignment.CenterVertically
101| ) {
102| // Score display
103| Column {
104| Text(
105| text = "Puntuació: $puntuacio",
106| fontSize = 24.sp,
107| fontWeight = FontWeight.Bold,
108| color = Color(0xFF2196F3)
109| )
110| Text(
111| text = "Intents: $intents",
112| fontSize = 16.sp,
113| color = Color.Gray
114| )
115| }
116| 
117| // Restart button
118| Button(
119| onClick = { iniciarPartida() },
120| colors = ButtonDefaults.buttonColors(
121| containerColor = Color(0xFF4CAF50)
122| ),
123| shape = RoundedCornerShape(8.dp)
124| ) {
125| Text(
126| text = "↻ Reiniciar",
127| fontSize = 16.sp,
128| fontWeight = FontWeight.Bold
129| )
130| }
131| }
132| 
133| // Game grid
134| LazyVerticalGrid(
135| columns = GridCells.Fixed(4),
136| modifier = Modifier
137| .weight(1f)
138| .padding(horizontal = 16.dp)
139| .padding(bottom = 80.dp),
140| horizontalArrangement = Arrangement.spacedBy(8.dp),
141| verticalArrangement = Arrangement.spacedBy(8.dp)
142| ) {
143| itemsIndexed(tauler) { index, cardValue ->
144| MemoryCard(
145| cardValue = cardValue,
146| isVisible = visibleCards[index] || matchedCards[index],
147| isMatched = matchedCards[index],
148| img = img,
149| fons = fons,
150| enabled = !bloc && !showInitialCards && !matchedCards[index],
151| onClick = {
152| if (!bloc && !visibleCards[index] && !matchedCards[index]) {
153| if (primer == null) {
154| // First card clicked
155| primer = index
156| numPrimer = tauler[index]
157| visibleCards = visibleCards.toMutableList().apply { set(index, true) }
158| } else {
159| // Second card clicked
160| bloc = true
161| val numSegon = tauler[index]
162| visibleCards = visibleCards.toMutableList().apply { set(index, true) }
163|
164| if (numPrimer == numSegon) {
165| // Match found - add points
166| matchedCards = matchedCards.toMutableList().apply {
167| set(primer!!, true)
168| set(index, true)
169| }
170| puntuacio += 10 // +10 points for a match
171| intents++
172| primer = null
173| bloc = false
174| } else {
175| // No match - subtract points
176| puntuacio -= 2 // -2 points for a miss
177| intents++
178| val primerIndex = primer!!
179| coroutineScope.launch {
180| delay(1000)
181| visibleCards = visibleCards.toMutableList().apply {
182| set(primerIndex, false)
183| set(index, false)
184| }
185| primer = null
186| bloc = false
187| }
188| }
189| }
190| }
191| }
192| )
193| }
194| }
195| }
196|
197| // Back button at the bottom
198| Box(
199| modifier = Modifier
200| .fillMaxSize()
201| .padding(bottom = 16.dp, start = 16.dp, end = 16.dp),
202| contentAlignment = Alignment.BottomCenter
203| ) {
204| Button(
205| onClick = onNavigateBack,
206| colors = ButtonDefaults.buttonColors(
207| containerColor = Color(0xFF607D8B)
208| ),
209| shape = RoundedCornerShape(8.dp),
210| modifier = Modifier.fillMaxWidth()
211| ) {
212| Text(
213| text = "← Tornar al Menú",
214| fontSize = 18.sp,
215| fontWeight = FontWeight.Bold,
216| modifier = Modifier.padding(horizontal = 16.dp, vertical = 4.dp)
217| )
218| }
219| }
220| }
221|}
222|
223|@Composable
224|fun MemoryCard(
225| cardValue: Int,
226| isVisible: Boolean,
227| isMatched: Boolean,
228| img: IntArray,
229| fons: Int,
230| enabled: Boolean,
231| onClick: () -> Unit
232|) {
233| val imageResource = if (isVisible || isMatched) img[cardValue] else fons
234| 
235| Image(
236| painter = painterResource(id = imageResource),
237| contentDescription = "Memory card",
238| modifier = Modifier
239| .aspectRatio(1f)
240| .clickable(enabled = enabled) { onClick() },
241| contentScale = ContentScale.Crop
242| )
243|}
244|
245|private fun mesclar(longitud: Int): List<Int> {
246| val result = mutableListOf<Int>()
247| // Add each image twice (8 images x 2 = 16 cards)
248| for (i in 0 until longitud) {
249| result.add(i)
250| result.add(i)
251| }
252| return result.shuffled()
253|}
