 cellState = board[5],
 onClick = { handlePlayerMove(5) }
 )
 }
 Row(modifier = Modifier.weight(1f)) {
 GameButton(
 modifier = Modifier.weight(1f),
 cellState = board[6],
 onClick = { handlePlayerMove(6) }
 )
 GameButton(
 modifier = Modifier.weight(1f),
 cellState = board[7],
 onClick = { handlePlayerMove(7) }
 )
 GameButton(
 modifier = Modifier.weight(1f),
 cellState = board[8],
 onClick = { handlePlayerMove(8) }
 )
 }
 }
 }
 }

 if (gameOver) {
 val message = when (winner) {
 CellState.O -> "You Win! "
 CellState.X -> "AI Wins!"
 else -> "It's a Tie!"
 }
 Box(
 modifier = Modifier
 .fillMaxSize()
 .padding(top = 140.dp),
