 33|@OptIn(ExperimentalMaterial3Api::class)
 34|@Composable
 35|fun MemoryScreen(onNavigateBack: () -> Unit = {}) {
 36| // Coroutine scope for async operations
 37| val coroutineScope = rememberCoroutineScope()
 38| 
 39| // State variables
 40| var tauler by remember { mutableStateOf(List(16) { 0 }) }
 41| var visibleCards by remember { mutableStateOf(List(16) { false }) }
 42| var matchedCards by remember { mutableStateOf(List(16) { false }) }
 43| var primer by remember { mutableStateOf<Int?>(null) }
 44| var numPrimer by remember { mutableStateOf(0) }
 45| var bloc by remember { mutableStateOf(false) }
 46| var showInitialCards by remember { mutableStateOf(true) }
 47| var puntuacio by remember { mutableStateOf(0) }
 48| var intents by remember { mutableStateOf(0) }
 49|
 50| // Image resources (you'll need to replace these with your actual drawable resources)
 51| val img = remember {
 52| intArrayOf(
 53| R.drawable.la0,
 54| R.drawable.la1,
 55| R.drawable.la2,
 56| R.drawable.la3,
 57| R.drawable.la4,
 58| R.drawable.la5,
 59| R.drawable.la6,
 60| R.drawable.la7
 61| )
 62| }
 63| val fons = R.drawable.fondo
 64|
 65| // Function to initialize/restart the game
 66| fun iniciarPartida() {
 67| coroutineScope.launch {
 68| // Block interaction first and hide everything
 69| showInitialCards = true
 70| visibleCards = List(16) { false }
 71| matchedCards = List(16) { false }
 72| 
 73| // Small delay to ensure UI updates
 74| delay(50)
 75| 
 76| // Reset all game state
 77| val arrayDesordre = mesclar(img.size)
 78| tauler = arrayDesordre
 79| primer = null
 80| numPrimer = 0
 81| bloc = false
 82| puntuacio = 0
 83| intents = 0
 84| 
 85| // Show all cards initially for preview
 86| visibleCards = List(16) { true }
 87| delay(1500)
 88| 
 89| // Hide all cards after delay
 90| visibleCards = List(16) { false }
 91| showInitialCards = false
 92| }
 93| }
 94|
 95| // Initialize the game on first load
 96| LaunchedEffect(Unit) {
 97| iniciarPartida()
 98| }
 99|
100| Box(modifier = Modifier.fillMaxSize()) {
101| Column(modifier = Modifier.fillMaxSize()) {
102| // Top App Bar
103| TopAppBar(
104| title = { Text("Memory Game") },
105| navigationIcon = {
106| IconButton(onClick = onNavigateBack) {
107| Icon(
108| imageVector = Icons.AutoMirrored.Filled.ArrowBack,
109| contentDescription = "Tornar al Menú"
110| )
111| }
112| },
113| colors = TopAppBarDefaults.topAppBarColors(
114| containerColor = Color(0xFF607D8B),
115| titleContentColor = Color.White,
116| navigationIconContentColor = Color.White
117| )
118| )
119| 
120| // Score and restart section at the top
121| Row(
122| modifier = Modifier
123| .fillMaxWidth()
124| .padding(16.dp),
125| horizontalArrangement = Arrangement.SpaceBetween,
126| verticalAlignment = Alignment.CenterVertically
127| ) {
128| // Score display
129| Column {
130| Text(
131| text = "Puntuació: $puntuacio",
132| fontSize = 24.sp,
133| fontWeight = FontWeight.Bold,
134| color = Color(0xFF2196F3)
135| )
136| Text(
137| text = "Intents: $intents",
138| fontSize = 16.sp,
139| color = Color.Gray
140| )
141| }
142| 
143| // Restart button
144| Button(
145| onClick = { iniciarPartida() },
146| colors = ButtonDefaults.buttonColors(
147| containerColor = Color(0xFF4CAF50)
148| ),
149| shape = RoundedCornerShape(8.dp)
150| ) {
151| Text(
152| text = "↻ Reiniciar",
153| fontSize = 16.sp,
154| fontWeight = FontWeight.Bold
155| )
156| }
157| }
158| 
159| // Game grid
160| LazyVerticalGrid(
161| columns = GridCells.Fixed(4),
162| modifier = Modifier
163| .weight(1f)
164| .padding(horizontal = 16.dp)
165| .padding(bottom = 16.dp),
166| horizontalArrangement = Arrangement.spacedBy(8.dp),
167| verticalArrangement = Arrangement.spacedBy(8.dp)
168| ) {
169| itemsIndexed(tauler) { index, cardValue ->
170| MemoryCard(
171| cardValue = cardValue,
172| isVisible = visibleCards[index] || matchedCards[index],
173| isMatched = matchedCards[index],
174| img = img,
175| fons = fons,
176| enabled = !bloc && !showInitialCards && !matchedCards[index],
177| onClick = {
178| if (!bloc && !visibleCards[index] && !matchedCards[index]) {
179| if (primer == null) {
180| // First card clicked
181| primer = index
182| numPrimer = tauler[index]
183| visibleCards = visibleCards.toMutableList().apply { set(index, true) }
184| } else {
185| // Second card clicked
186| bloc = true
187| val numSegon = tauler[index]
188| visibleCards = visibleCards.toMutableList().apply { set(index, true) }
189|
190| if (numPrimer == numSegon) {
191| // Match found - add points
192| matchedCards = matchedCards.toMutableList().apply {
193| set(primer!!, true)
194| set(index, true)
195| }
196| puntuacio += 10 // +10 points for a match
197| intents++
198| primer = null
199| bloc = false
200| } else {
201| // No match - subtract points
202| puntuacio -= 2 // -2 points for a miss
203| intents++
204| val primerIndex = primer!!
205| coroutineScope.launch {
206| delay(1000)
207| visibleCards = visibleCards.toMutableList().apply {
208| set(primerIndex, false)
209| set(index, false)
210| }
211| primer = null
212| bloc = false
213| }
214| }
215| }
216| }
217| }
218| )
219| }
220| }
221| }
222| }
