225|@Composable
226|fun MemoryCard(
227| cardValue: Int,
228| isVisible: Boolean,
229| isMatched: Boolean,
230| img: IntArray,
231| fons: Int,
232| enabled: Boolean,
233| onClick: () -> Unit
234|) {
235| val imageResource = if (isVisible || isMatched) img[cardValue] else fons
236| 
237| Image(
238| painter = painterResource(id = imageResource),
239| contentDescription = "Memory card",
240| modifier = Modifier
241| .aspectRatio(1f)
242| .clickable(enabled = enabled) { onClick() },
243| contentScale = ContentScale.Crop
244| )
245|}
246|
247|private fun mesclar(longitud: Int): List<Int> {
248| val result = mutableListOf<Int>()
249| // Add each image twice (8 images x 2 = 16 cards)
250| for (i in 0 until longitud) {
251| result.add(i)
252| result.add(i)
253| }
254| return result.shuffled()
255|}
