253|fun MemoryCard(
254| cardValue: Int,
255| isVisible: Boolean,
256| isMatched: Boolean,
257| img: IntArray,
258| fons: Int,
259| enabled: Boolean,
260| onClick: () -> Unit
261|) {
262| val imageResource = if (isVisible || isMatched) img[cardValue] else fons
263| 
264| Image(
265| painter = painterResource(id = imageResource),
266| contentDescription = "Memory card",
267| modifier = Modifier
268| .aspectRatio(1f)
269| .clickable(enabled = enabled) { onClick() },
270| contentScale = ContentScale.Crop
271| )
272|}
