274|private fun mesclar(longitud: Int): List<Int> {
275| val result = mutableListOf<Int>()
276| // Add each image twice (8 images x 2 = 16 cards)
277| for (i in 0 until longitud) {
278| result.add(i)
279| result.add(i)
280| }
281| return result.shuffled()
282|}
