189| bloc = true
190| val numSegon = tauler[index]
191| visibleCards = visibleCards.toMutableList().apply { set(index, true) }
192|
193| if (numPrimer == numSegon) {
194| // Match found - add points
195| matchedCards = matchedCards.toMutableList().apply {
196| set(primer!!, true)
197| set(index, true)
198| }
199| puntuacio += 10 // +10 points for a match
200| intents++
201| primer = null
202| bloc = false
203| } else {
204| // No match - subtract points
205| puntuacio -= 2 // -2 points for a miss
206| intents++
207| val primerIndex = primer!!
208| coroutineScope.launch {
209| delay(1000)
210| visibleCards = visibleCards.toMutableList().apply {
211| set(primerIndex, false)
212| set(index, false)
213| }
214| primer = null
215| bloc = false
216| }
217| }
218| }
219| }
220| }
221| )
222| }
223| }
224| }
225| 
226| // Restart button at the bottom
227| Box(
228| modifier = Modifier
229| .fillMaxSize()
230| .padding(bottom = 40.dp, start = 12.dp, end = 12.dp),
231| contentAlignment = Alignment.BottomCenter
232| ) {
233| Button(
234| onClick = { iniciarPartida() },
235| colors = ButtonDefaults.buttonColors(
236| containerColor = Color(0xFF4CAF50)
237| ),
238| shape = RoundedCornerShape(8.dp),
239| modifier = Modifier.fillMaxWidth()
240| ) {
241| Text(
242| text = "↻ Reiniciar",
243| fontSize = 20.sp,
244| fontWeight = FontWeight.Bold,
245| modifier = Modifier.padding(horizontal = 16.dp, vertical = 4.dp)
246| )
247| }
248| }
249| }
