 48|enum class CellState {
 49| EMPTY, O, X
 50|}
 51|
 52|@OptIn(ExperimentalMaterial3Api::class)
 53|@Composable
 54|fun TresEnRatllaScreen(onNavigateBack: () -> Unit = {}) {
 55| var board by remember { mutableStateOf(List(9) { CellState.EMPTY }) }
 56| var gameOver by remember { mutableStateOf(false) }
 57| var winner by remember { mutableStateOf<CellState?>(null) }
 58| var aiShouldMove by remember { mutableStateOf(false) }
 59|
 60| // Marcador
 61| var wins by remember { mutableStateOf(0) }
 62| var losses by remember { mutableStateOf(0) }
 63| var ties by remember { mutableStateOf(0) }
 64|
 65| // Check for winner after each move
 66| fun checkWinner(): CellState? {
 67| val winPatterns = listOf(
 68| listOf(0, 1, 2), listOf(3, 4, 5), listOf(6, 7, 8), // Rows
 69| listOf(0, 3, 6), listOf(1, 4, 7), listOf(2, 5, 8), // Columns
 70| listOf(0, 4, 8), listOf(2, 4, 6) // Diagonals
 71| )
 72|
 73| for (pattern in winPatterns) {
 74| val (a, b, c) = pattern
 75| if (board[a] != CellState.EMPTY &&
 76| board[a] == board[b] &&
 77| board[b] == board[c]
 78| ) {
 79| return board[a]
 80| }
 81| }
 82|
 83| if (board.none { it == CellState.EMPTY }) {
 84| return CellState.EMPTY
 85| }
 86|
 87| return null
 88| }
 89|
 90| fun handlePlayerMove(index: Int) {
 91| if (board[index] == CellState.EMPTY && !gameOver && !aiShouldMove) {
 92| board = board.toMutableList().apply { this[index] = CellState.O }
 93|
 94| val result = checkWinner()
 95| if (result != null) {
 96| gameOver = true
 97| winner = result
 98| // Actualitzar marcador
 99| when (result) {
100| CellState.O -> wins++
101| CellState.X -> losses++
102| else -> ties++
103| }
104| } else {
105| aiShouldMove = true
106| }
107| }
108| }
109|
110| LaunchedEffect(aiShouldMove) {
111| if (aiShouldMove) {
112| delay(200) // 0.2 second delay
113| board = aiMove(board)
114| val aiResult = checkWinner()
115| if (aiResult != null) {
116| gameOver = true
117| winner = aiResult
118| // Actualitzar marcador
119| when (aiResult) {
120| CellState.O -> wins++
121| CellState.X -> losses++
122| else -> ties++
123| }
124| }
125| aiShouldMove = false
126| }
127| }
128|
129| fun resetGame() {
130| board = List(9) { CellState.EMPTY }
131| gameOver = false
132| winner = null
133| aiShouldMove = false
134| }
135|
136| fun resetScore() {
137| wins = 0
138| losses = 0
139| ties = 0
140| resetGame()
141| }
