178| horizontalArrangement = Arrangement.SpaceEvenly
179| ) {
180| ScoreItem(label = "Victòries", value = wins, color = Color(0xFF4CAF50))
181| ScoreItem(label = "Empats", value = ties, color = Color(0xFFFF9800))
182| ScoreItem(label = "Derrotes", value = losses, color = Color(0xFFF44336))
183| }
184|
185| Spacer(modifier = Modifier.height(32.dp))
186|
187| // Tauler de joc amb grid dinàmic
188| Box(
189| modifier = Modifier
190| .fillMaxWidth()
191| .padding(horizontal = 32.dp)
192| .aspectRatio(1f)
193| ) {
194| // Dibuixar la graella
195| Canvas(modifier = Modifier.fillMaxSize()) {
196| val canvasWidth = size.width
197| val canvasHeight = size.height
198| val cellSize = canvasWidth / 3
199|
200| // Línies verticals
201| drawLine(
202| color = Color.Black,
203| start = Offset(cellSize, 0f),
204| end = Offset(cellSize, canvasHeight),
205| strokeWidth = 8f,
206| cap = StrokeCap.Round
207| )
208| drawLine(
209| color = Color.Black,
210| start = Offset(cellSize * 2, 0f),
211| end = Offset(cellSize * 2, canvasHeight),
212| strokeWidth = 8f,
213| cap = StrokeCap.Round
214| )
215|
216| // Línies horitzontals
217| drawLine(
218| color = Color.Black,
219| start = Offset(0f, cellSize),
220| end = Offset(canvasWidth, cellSize),
221| strokeWidth = 8f,
222| cap = StrokeCap.Round
223| )
224| drawLine(
225| color = Color.Black,
226| start = Offset(0f, cellSize * 2),
227| end = Offset(canvasWidth, cellSize * 2),
228| strokeWidth = 8f,
229| cap = StrokeCap.Round
230| )
231| }
232|
233| // Cel·les del joc
234| Column(modifier = Modifier.fillMaxSize()) {
235| Row(modifier = Modifier.weight(1f)) {
236| GameButton(
237| modifier = Modifier.weight(1f),
238| cellState = board[0],
239| onClick = { handlePlayerMove(0) }
240| )
241| GameButton(
242| modifier = Modifier.weight(1f),
243| cellState = board[1],
244| onClick = { handlePlayerMove(1) }
245| )
246| GameButton(
247| modifier = Modifier.weight(1f),
248| cellState = board[2],
249| onClick = { handlePlayerMove(2) }
250| )
251| }
252| Row(modifier = Modifier.weight(1f)) {
