255| cellState = board[3],
256| onClick = { handlePlayerMove(3) }
257| )
258| GameButton(
259| modifier = Modifier.weight(1f),
260| cellState = board[4],
261| onClick = { handlePlayerMove(4) }
262| )
263| GameButton(
264| modifier = Modifier.weight(1f),
265| cellState = board[5],
266| onClick = { handlePlayerMove(5) }
267| )
268| }
269| Row(modifier = Modifier.weight(1f)) {
270| GameButton(
271| modifier = Modifier.weight(1f),
272| cellState = board[6],
273| onClick = { handlePlayerMove(6) }
274| )
275| GameButton(
276| modifier = Modifier.weight(1f),
