282| cellState = board[8],
283| onClick = { handlePlayerMove(8) }
284| )
285| }
286| }
287| }
288| }
289|
290| if (gameOver) {
291| val message = when (winner) {
292| CellState.O -> "You Win! "
293| CellState.X -> "AI Wins!"
294| else -> "It's a Tie!"
