323| shape = RoundedCornerShape(8.dp),
324| modifier = Modifier.fillMaxWidth()
325| ) {
326| Text(
327| text = "Nova Partida",
328| fontSize = 20.sp,
329| fontWeight = FontWeight.Bold,
