375|fun aiMove(board: List<CellState>): List<CellState> {
376| val emptyIndices = board.indices.filter { board[it] == CellState.EMPTY }
377|
378| if (emptyIndices.isEmpty()) {
379| return board
380| }
381|
382| val randomIndex = emptyIndices[Random.nextInt(emptyIndices.size)]
383| return board.toMutableList().apply { this[randomIndex] = CellState.X }
384|}
