enum class CellState {
 EMPTY, O, X
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun TresEnRatllaScreen(onNavigateBack: () -> Unit = {}) {
 var board by remember { mutableStateOf(List(9) { CellState.EMPTY }) }
 var gameOver by remember { mutableStateOf(false) }
 var winner by remember { mutableStateOf<CellState?>(null) }
 var aiShouldMove by remember { mutableStateOf(false) }

 // Marcador
 var wins by remember { mutableStateOf(0) }
 var losses by remember { mutableStateOf(0) }
 var ties by remember { mutableStateOf(0) }

 // Check for winner after each move
 fun checkWinner(): CellState? {
 val winPatterns = listOf(
 listOf(0, 1, 2), listOf(3, 4, 5), listOf(6, 7, 8), // Rows
 listOf(0, 3, 6), listOf(1, 4, 7), listOf(2, 5, 8), // Columns
 listOf(0, 4, 8), listOf(2, 4, 6) // Diagonals
 )

 for (pattern in winPatterns) {
 val (a, b, c) = pattern
 if (board[a] != CellState.EMPTY &&
 board[a] == board[b] &&
 board[b] == board[c]
 ) {
 return board[a]
 }
 }

 if (board.none { it == CellState.EMPTY }) {
 return CellState.EMPTY
 }

 return null
 }

 fun handlePlayerMove(index: Int) {
 if (board[index] == CellState.EMPTY && !gameOver && !aiShouldMove) {
 board = board.toMutableList().apply { this[index] = CellState.O }

 val result = checkWinner()
 if (result != null) {
 gameOver = true
 winner = result
 // Actualitzar marcador
 when (result) {
 CellState.O -> wins++
 CellState.X -> losses++
 else -> ties++
 }
 } else {
 aiShouldMove = true
 }
 }
 }

 LaunchedEffect(aiShouldMove) {
 if (aiShouldMove) {
 delay(200) // 0.2 second delay
 board = aiMove(board)
 val aiResult = checkWinner()
 if (aiResult != null) {
 gameOver = true
 winner = aiResult
 // Actualitzar marcador
 when (aiResult) {
 CellState.O -> wins++
 CellState.X -> losses++
 else -> ties++
 }
 }
 aiShouldMove = false
 }
 }

 fun resetGame() {
 board = List(9) { CellState.EMPTY }
 gameOver = false
 winner = null
 aiShouldMove = false
 }

 fun resetScore() {
 wins = 0
 losses = 0
 ties = 0
 resetGame()
 }

 Box(
 modifier = Modifier
 .fillMaxSize()
 .background(White)
 ) {
 // Top App Bar
 TopAppBar(
 title = { Text("Tres en Ratlla", fontFamily = MinecraftFont) },
 navigationIcon = {
 IconButton(onClick = onNavigateBack) {
 Icon(
 imageVector = Icons.AutoMirrored.Filled.ArrowBack,
 contentDescription = "Tornar al Menú"
 )
 }
 },
 colors = TopAppBarDefaults.topAppBarColors(
 containerColor = Color(0xFF607D8B),
 titleContentColor = White,
 navigationIconContentColor = White
 )
 )

 Column(
 modifier = Modifier
 .fillMaxSize()
 .padding(top = 64.dp, bottom = 100.dp),
 horizontalAlignment = Alignment.CenterHorizontally,
 verticalArrangement = Arrangement.Center
 ) {
 // Marcador
 Row(
 modifier = Modifier
 .fillMaxWidth()
 .padding(start = 32.dp, end = 32.dp, top = 16.dp),
 horizontalArrangement = Arrangement.SpaceEvenly
 ) {
 ScoreItem(label = "Victories", value = wins, color = Color(0xFF4CAF50))
 ScoreItem(label = "Empats", value = ties, color = Color(0xFFFF9800))
 ScoreItem(label = "Derrotes", value = losses, color = Color(0xFFF44336))
 }

 Spacer(modifier = Modifier.height(32.dp))

 // Tauler de joc amb grid dinàmic
 Box(
 modifier = Modifier
 .fillMaxWidth()
 .padding(horizontal = 32.dp)
 .aspectRatio(1f)
 ) {
 // Dibuixar la graella
 Canvas(modifier = Modifier.fillMaxSize()) {
 val canvasWidth = size.width
 val canvasHeight = size.height
 val cellSize = canvasWidth / 3

 // Línies verticals
 drawLine(
 color = Color.Black,
 start = Offset(cellSize, 0f),
 end = Offset(cellSize, canvasHeight),
 strokeWidth = 8f,
 cap = StrokeCap.Round
 )
 drawLine(
 color = Color.Black,
 start = Offset(cellSize * 2, 0f),
 end = Offset(cellSize * 2, canvasHeight),
 strokeWidth = 8f,
 cap = StrokeCap.Round
 )

 // Línies horitzontals
 drawLine(
 color = Color.Black,
 start = Offset(0f, cellSize),
 end = Offset(canvasWidth, cellSize),
 strokeWidth = 8f,
 cap = StrokeCap.Round
 )
 drawLine(
 color = Color.Black,
 start = Offset(0f, cellSize * 2),
 end = Offset(canvasWidth, cellSize * 2),
 strokeWidth = 8f,
 cap = StrokeCap.Round
 )
 }

 // Cel·les del joc
 Column(modifier = Modifier.fillMaxSize()) {
 Row(modifier = Modifier.weight(1f)) {
 GameButton(
 modifier = Modifier.weight(1f),
 cellState = board[0],
 onClick = { handlePlayerMove(0) }
 )
 GameButton(
 modifier = Modifier.weight(1f),
 cellState = board[1],
 onClick = { handlePlayerMove(1) }
 )
 GameButton(
 modifier = Modifier.weight(1f),
 cellState = board[2],
 onClick = { handlePlayerMove(2) }
 )
 }
 Row(modifier = Modifier.weight(1f)) {
 GameButton(
 modifier = Modifier.weight(1f),
 cellState = board[3],
 onClick = { handlePlayerMove(3) }
 )
 GameButton(
 modifier = Modifier.weight(1f),
 cellState = board[4],
 onClick = { handlePlayerMove(4) }
 )
 GameButton(
 modifier = Modifier.weight(1f),
 cellState = board[5],
 onClick = { handlePlayerMove(5) }
 )
 }
 Row(modifier = Modifier.weight(1f)) {
 GameButton(
 modifier = Modifier.weight(1f),
 cellState = board[6],
 onClick = { handlePlayerMove(6) }
 )
 GameButton(
 modifier = Modifier.weight(1f),
 cellState = board[7],
 onClick = { handlePlayerMove(7) }
 )
 GameButton(
 modifier = Modifier.weight(1f),
 cellState = board[8],
 onClick = { handlePlayerMove(8) }
 )
 }
 }
 }
 }

 if (gameOver) {
 val message = when (winner) {
 CellState.O -> "You Win! "
 CellState.X -> "AI Wins!"
 else -> "It's a Tie!"
 }
 Box(
 modifier = Modifier
 .fillMaxSize()
 .padding(top = 140.dp),
 contentAlignment = Alignment.TopCenter
 ) {
 Text(
 text = message,
 fontSize = 32.sp,
 fontWeight = FontWeight.Bold,
 fontFamily = MinecraftFont,
 color = Color.Black
 )
 }
 }

 Box(
 modifier = Modifier
 .fillMaxSize()
 .padding(bottom = 40.dp, start = 12.dp, end = 12.dp),
 contentAlignment = Alignment.BottomCenter
 ) {
 Column {
 Button(
 onClick = { resetGame() },
 colors = ButtonDefaults.buttonColors(
 containerColor = Color(0xFF2196F3)
 ),
 shape = RoundedCornerShape(8.dp),
 modifier = Modifier.fillMaxWidth()
 ) {
 Text(
 text = "Nova Partida",
 fontSize = 20.sp,
 fontWeight = FontWeight.Bold,
 modifier = Modifier.padding(horizontal = 16.dp, vertical = 4.dp)
 )
 }

 Spacer(modifier = Modifier.height(8.dp))

 Button(
 onClick = { resetScore() },
 colors = ButtonDefaults.buttonColors(
 containerColor = Color(0xFF9E9E9E)
 ),
 shape = RoundedCornerShape(8.dp),
 modifier = Modifier.fillMaxWidth()
 ) {
 Text(
 text = "Reiniciar Marcador",
 fontSize = 18.sp,
 fontWeight = FontWeight.Bold,
 modifier = Modifier.padding(horizontal = 16.dp, vertical = 4.dp)
 )
 }
 }
 }
 }
}

@Composable
fun ScoreItem(label: String, value: Int, color: Color) {
 Column(
 horizontalAlignment = Alignment.CenterHorizontally
 ) {
 Text(
 text = value.toString(),
 fontSize = 28.sp,
 fontWeight = FontWeight.Bold,
 color = color
 )
 Text(
 text = label,
 fontSize = 14.sp,
 color = Color.DarkGray
 )
 }
}

fun aiMove(board: List<CellState>): List<CellState> {
 val emptyIndices = board.indices.filter { board[it] == CellState.EMPTY }

 if (emptyIndices.isEmpty()) {
 return board
 }

 val randomIndex = emptyIndices[Random.nextInt(emptyIndices.size)]
 return board.toMutableList().apply { this[randomIndex] = CellState.X }
}

@Composable
fun GameButton(
 modifier: Modifier = Modifier,
 cellState: CellState,
 onClick: () -> Unit
) {
 Box(
 modifier
 .fillMaxSize()
 .clickable { onClick() }
 .padding(16.dp),
 contentAlignment = Alignment.Center,
 ) {
 when (cellState) {
 CellState.O -> {
 Image(
 modifier = Modifier.fillMaxSize(),
 painter = painterResource(R.drawable.o),
 contentDescription = "O"
 )
 }

 CellState.X -> {
 Image(
 modifier = Modifier.fillMaxSize(),
 painter = painterResource(R.drawable.x),
 contentDescription = "X"
 )
 }

 CellState.EMPTY -> {
 // Empty cell - no image
 }
 }
 }
}

