 // Dibuixar la graella
 Canvas(modifier = Modifier.fillMaxSize()) {
 val canvasWidth = size.width
 val canvasHeight = size.height
 val cellSize = canvasWidth / 3
 val shadowColor = Color.Black.copy(alpha = 0.4f)

 // Línies verticals amb ombra
 // Shadow for first vertical line
 drawLine(
 color = shadowColor,
 start = Offset(cellSize + 2f, 2f),
 end = Offset(cellSize + 2f, canvasHeight + 2f),
 strokeWidth = 12f,
 cap = StrokeCap.Round
 )
 drawLine(
 color = White,
 start = Offset(cellSize, 0f),
 end = Offset(cellSize, canvasHeight),
 strokeWidth = 8f,
 cap = StrokeCap.Round
 )
 
 // Shadow for second vertical line
 drawLine(
 color = shadowColor,
 start = Offset(cellSize * 2 + 2f, 2f),
 end = Offset(cellSize * 2 + 2f, canvasHeight + 2f),
 strokeWidth = 12f,
 cap = StrokeCap.Round
 )
 drawLine(
 color = White,
 start = Offset(cellSize * 2, 0f),
