 strokeWidth = 8f,
 cap = StrokeCap.Round
 )

 // Línies horitzontals amb ombra
 // Shadow for first horizontal line
 drawLine(
 color = shadowColor,
 start = Offset(2f, cellSize + 2f),
 end = Offset(canvasWidth + 2f, cellSize + 2f),
 strokeWidth = 12f,
 cap = StrokeCap.Round
 )
 drawLine(
 color = White,
 start = Offset(0f, cellSize),
 end = Offset(canvasWidth, cellSize),
 strokeWidth = 8f,
 cap = StrokeCap.Round
 )
 
 // Shadow for second horizontal line
 drawLine(
 color = shadowColor,
 start = Offset(2f, cellSize * 2 + 2f),
 end = Offset(canvasWidth + 2f, cellSize * 2 + 2f),
 strokeWidth = 12f,
 cap = StrokeCap.Round
