 ),
 shape = RoundedCornerShape(0.dp),
 border = BorderStroke(2.dp, Color.Black),
 modifier = Modifier
 .fillMaxWidth()
 .height(60.dp)
 ) {
 Text(
 text = "Nova Partida",
 fontSize = 24.sp,
 fontWeight = FontWeight.Bold,
 fontFamily = MinecraftFont,
 letterSpacing = 2.sp,
 style = TextStyle(
 shadow = Shadow(
 color = Color.Black,
 offset = Offset(4f, 4f),
 blurRadius = 3f
 )
 )
 )
 }

 Spacer(modifier = Modifier.height(8.dp))

 Button(
 onClick = { resetScore() },
 colors = ButtonDefaults.buttonColors(
