 )

 // Línies horitzontals amb ombra
 // Shadow for first horizontal line
 drawLine(
 color = shadowColor,
 start = Offset(2f, cellSize + 2f),
 end = Offset(canvasWidth + 2f, cellSize + 2f),
 strokeWidth = 12f,
 cap = StrokeCap.Round
 )
 drawLine(
