 39|@OptIn(ExperimentalMaterial3Api::class)
 40|@Composable
 41|fun MemoryScreen(onNavigateBack: () -> Unit = {}) {
 42| // Coroutine scope for async operations
 43| val coroutineScope = rememberCoroutineScope()
 44| 
 45| // State variables
 46| var tauler by remember { mutableStateOf(List(16) { 0 }) }
 47| var visibleCards by remember { mutableStateOf(List(16) { false }) }
 48| var matchedCards by remember { mutableStateOf(List(16) { false }) }
 49| var primer by remember { mutableStateOf<Int?>(null) }
 50| var numPrimer by remember { mutableStateOf(0) }
 51| var bloc by remember { mutableStateOf(false) }
 52| var showInitialCards by remember { mutableStateOf(true) }
 53| var puntuacio by remember { mutableStateOf(0) }
 54| var intents by remember { mutableStateOf(0) }
 55|
 56| // Image resources (you'll need to replace these with your actual drawable resources)
 57| val img = remember {
 58| intArrayOf(
 59| R.drawable.la0,
 60| R.drawable.la1,
 61| R.drawable.la2,
 62| R.drawable.la3,
 63| R.drawable.la4,
 64| R.drawable.la5,
 65| R.drawable.la6,
 66| R.drawable.la7
 67| )
 68| }
 69| val fons = R.drawable.fondo
 70|
 71| // Function to initialize/restart the game
 72| fun iniciarPartida() {
 73| coroutineScope.launch {
 74| // Block interaction first and hide everything
 75| showInitialCards = true
 76| visibleCards = List(16) { false }
 77| matchedCards = List(16) { false }
 78| 
 79| // Small delay to ensure UI updates
 80| delay(50)
 81| 
 82| // Reset all game state
 83| val arrayDesordre = mesclar(img.size)
 84| tauler = arrayDesordre
 85| primer = null
 86| numPrimer = 0
 87| bloc = false
 88| puntuacio = 0
 89| intents = 0
 90| 
 91| // Show all cards initially for preview
 92| visibleCards = List(16) { true }
 93| delay(1500)
 94| 
 95| // Hide all cards after delay
 96| visibleCards = List(16) { false }
 97| showInitialCards = false
 98| }
 99| }
100|
101| // Initialize the game on first load
102| LaunchedEffect(Unit) {
103| iniciarPartida()
104| }
105|
106| Box(
107| modifier = Modifier
108| .fillMaxSize()
109| .background(Color(0xFFC6C6C6))
110| ) {
111| // Top App Bar
112| TopAppBar(
113| title = { Text("Memory Game", fontFamily = MinecraftFont, letterSpacing = 2.sp) },
114| navigationIcon = {
115| IconButton(onClick = onNavigateBack) {
116| Icon(
117| imageVector = Icons.AutoMirrored.Filled.ArrowBack,
118| contentDescription = "Tornar al Menú"
119| )
120| }
121| },
122| colors = TopAppBarDefaults.topAppBarColors(
123| containerColor = Color(0xFF6F6F6F),
124| titleContentColor = Color.White,
125| navigationIconContentColor = Color.White
126| )
127| )
128| 
129| Column(
130| modifier = Modifier
131| .fillMaxSize()
132| .padding(top = 64.dp, bottom = 100.dp)
133| ) {
134| // Score display section at the top
135| Row(
136| modifier = Modifier
137| .fillMaxWidth()
138| .padding(start = 16.dp, end = 16.dp, top = 128.dp, bottom = 16.dp),
139| horizontalArrangement = Arrangement.SpaceEvenly,
140| verticalAlignment = Alignment.CenterVertically
141| ) {
142| // Score display
143| Column(horizontalAlignment = Alignment.CenterHorizontally) {
144| Text(
145| text = puntuacio.toString(),
146| fontSize = 28.sp,
147| fontWeight = FontWeight.Bold,
148| fontFamily = MinecraftFont,
149| color = Color.White,
150| letterSpacing = 2.sp,
151| style = TextStyle(
152| shadow = Shadow(
153| color = Color.Black,
154| offset = Offset(4f, 4f),
155| blurRadius = 3f
156| )
157| )
158| )
159| Text(
160| text = "Puntuacio",
161| fontSize = 14.sp,
162| fontFamily = MinecraftFont,
163| color = Color.DarkGray,
164| letterSpacing = 2.sp
165| )
166| }
167| 
168| Column(horizontalAlignment = Alignment.CenterHorizontally) {
169| Text(
170| text = intents.toString(),
171| fontSize = 28.sp,
172| fontWeight = FontWeight.Bold,
173| fontFamily = MinecraftFont,
174| color = Color.White,
175| letterSpacing = 2.sp,
176| style = TextStyle(
177| shadow = Shadow(
178| color = Color.Black,
179| offset = Offset(4f, 4f),
180| blurRadius = 3f
181| )
182| )
183| )
184| Text(
185| text = "Intents",
186| fontSize = 14.sp,
187| fontFamily = MinecraftFont,
188| color = Color.DarkGray,
189| letterSpacing = 2.sp
190| )
191| }
192| }
193| 
194| // Game grid
195| LazyVerticalGrid(
196| columns = GridCells.Fixed(4),
197| modifier = Modifier
198| .weight(1f)
199| .padding(horizontal = 16.dp)
200| .padding(bottom = 16.dp),
201| horizontalArrangement = Arrangement.spacedBy(8.dp),
202| verticalArrangement = Arrangement.spacedBy(8.dp)
203| ) {
204| itemsIndexed(tauler) { index, cardValue ->
205| MemoryCard(
206| cardValue = cardValue,
207| isVisible = visibleCards[index] || matchedCards[index],
208| isMatched = matchedCards[index],
209| img = img,
210| fons = fons,
211| enabled = !bloc && !showInitialCards && !matchedCards[index],
212| onClick = {
213| if (!bloc && !visibleCards[index] && !matchedCards[index]) {
214| if (primer == null) {
215| // First card clicked
216| primer = index
217| numPrimer = tauler[index]
218| visibleCards = visibleCards.toMutableList().apply { set(index, true) }
219| } else {
220| // Second card clicked
221| bloc = true
222| val numSegon = tauler[index]
223| visibleCards = visibleCards.toMutableList().apply { set(index, true) }
224|
225| if (numPrimer == numSegon) {
226| // Match found - add points
227| matchedCards = matchedCards.toMutableList().apply {
228| set(primer!!, true)
229| set(index, true)
230| }
231| puntuacio += 10 // +10 points for a match
232| intents++
233| primer = null
234| bloc = false
235| } else {
236| // No match - subtract points
237| puntuacio -= 2 // -2 points for a miss
238| intents++
239| val primerIndex = primer!!
240| coroutineScope.launch {
241| delay(1000)
242| visibleCards = visibleCards.toMutableList().apply {
243| set(primerIndex, false)
244| set(index, false)
245| }
246| primer = null
247| bloc = false
248| }
249| }
250| }
251| }
252| }
253| )
254| }
255| }
256| }
257| 
258| // Restart button at the bottom
259| Box(
260| modifier = Modifier
261| .fillMaxSize()
262| .padding(bottom = 40.dp, start = 12.dp, end = 12.dp),
263| contentAlignment = Alignment.BottomCenter
264| ) {
265| Button(
266| onClick = { iniciarPartida() },
267| colors = ButtonDefaults.buttonColors(
268| containerColor = Color(0xFFA38E7C)
269| ),
270| shape = RoundedCornerShape(0.dp),
271| border = BorderStroke(2.dp, Color.Black),
272| modifier = Modifier
273| .fillMaxWidth()
274| .height(60.dp)
275| ) {
276| Text(
277| text = "↻ Reiniciar",
278| fontSize = 24.sp,
279| fontWeight = FontWeight.Bold,
280| fontFamily = MinecraftFont,
281| letterSpacing = 2.sp,
282| style = TextStyle(
283| shadow = Shadow(
284| color = Color.Black,
285| offset = Offset(4f, 4f),
286| blurRadius = 3f
287| )
288| )
289| )
290| }
291| }
292| }
293|}
