295|@Composable
296|fun MemoryCard(
297| cardValue: Int,
298| isVisible: Boolean,
299| isMatched: Boolean,
300| img: IntArray,
301| fons: Int,
302| enabled: Boolean,
303| onClick: () -> Unit
304|) {
305| val imageResource = if (isVisible || isMatched) img[cardValue] else fons
306| 
307| Image(
308| painter = painterResource(id = imageResource),
309| contentDescription = "Memory card",
310| modifier = Modifier
311| .aspectRatio(1f)
312| .clickable(enabled = enabled) { onClick() },
313| contentScale = ContentScale.Fit
314| )
315|}
316|
317|private fun mesclar(longitud: Int): List<Int> {
318| val result = mutableListOf<Int>()
319| // Add each image twice (8 images x 2 = 16 cards)
320| for (i in 0 until longitud) {
321| result.add(i)
322| result.add(i)
323| }
324| return result.shuffled()
325|}
