 53|
 54|enum class CellState {
 55| EMPTY, O, X
 56|}
 57|
 58|@OptIn(ExperimentalMaterial3Api::class)
 59|@Composable
 60|fun TresEnRatllaScreen(onNavigateBack: () -> Unit = {}) {
 61| var board by remember { mutableStateOf(List(9) { CellState.EMPTY }) }
 62| var gameOver by remember { mutableStateOf(false) }
 63| var winner by remember { mutableStateOf<CellState?>(null) }
 64| var aiShouldMove by remember { mutableStateOf(false) }
 65|
 66| // Marcador
 67| var wins by remember { mutableStateOf(0) }
 68| var losses by remember { mutableStateOf(0) }
 69| var ties by remember { mutableStateOf(0) }
 70|
 71| // Check for winner after each move
 72| fun checkWinner(): CellState? {
 73| val winPatterns = listOf(
 74| listOf(0, 1, 2), listOf(3, 4, 5), listOf(6, 7, 8), // Rows
 75| listOf(0, 3, 6), listOf(1, 4, 7), listOf(2, 5, 8), // Columns
 76| listOf(0, 4, 8), listOf(2, 4, 6) // Diagonals
 77| )
 78|
 79| for (pattern in winPatterns) {
 80| val (a, b, c) = pattern
 81| if (board[a] != CellState.EMPTY &&
 82| board[a] == board[b] &&
 83| board[b] == board[c]
 84| ) {
 85| return board[a]
 86| }
 87| }
 88|
 89| if (board.none { it == CellState.EMPTY }) {
 90| return CellState.EMPTY
 91| }
 92|
 93| return null
 94| }
 95|
 96| fun handlePlayerMove(index: Int) {
 97| if (board[index] == CellState.EMPTY && !gameOver && !aiShouldMove) {
 98| board = board.toMutableList().apply { this[index] = CellState.O }
 99|
100| val result = checkWinner()
101| if (result != null) {
102| gameOver = true
103| winner = result
104| // Actualitzar marcador
105| when (result) {
106| CellState.O -> wins++
107| CellState.X -> losses++
108| else -> ties++
109| }
110| } else {
111| aiShouldMove = true
112| }
113| }
114| }
115|
116| LaunchedEffect(aiShouldMove) {
117| if (aiShouldMove) {
118| delay(200) // 0.2 second delay
119| board = aiMove(board)
120| val aiResult = checkWinner()
121| if (aiResult != null) {
122| gameOver = true
123| winner = aiResult
124| // Actualitzar marcador
125| when (aiResult) {
126| CellState.O -> wins++
127| CellState.X -> losses++
128| else -> ties++
129| }
130| }
131| aiShouldMove = false
132| }
133| }
134|
135| fun resetGame() {
136| board = List(9) { CellState.EMPTY }
137| gameOver = false
138| winner = null
139| aiShouldMove = false
140| }
141|
142| fun resetScore() {
143| wins = 0
144| losses = 0
145| ties = 0
146| resetGame()
147| }
148|
149| Box(
