452|fun aiMove(board: List<CellState>): List<CellState> {
453| val emptyIndices = board.indices.filter { board[it] == CellState.EMPTY }
454|
455| if (emptyIndices.isEmpty()) {
456| return board
457| }
458|
459| val randomIndex = emptyIndices[Random.nextInt(emptyIndices.size)]
460| return board.toMutableList().apply { this[randomIndex] = CellState.X }
461|}
