472| .clickable { onClick() }
473| .padding(16.dp),
474| contentAlignment = Alignment.Center,
475| ) {
476| when (cellState) {
477| CellState.O -> {
478| Image(
479| modifier = Modifier.fillMaxSize(),
480| painter = painterResource(R.drawable.o),
481| contentDescription = "O"
482| )
483| }
484|
485| CellState.X -> {
486| Image(
487| modifier = Modifier.fillMaxSize(),
488| painter = painterResource(R.drawable.x),
489| contentDescription = "X"
490| )
491| }
492|
493| CellState.EMPTY -> {
494| // Empty cell - no image
495| }
496| }
497| }
