 cap = StrokeCap.Round
 )
 
 drawLine(
 color = shadowColor,
 start = Offset(cellSize * 2 + 2f, 2f),
 end = Offset(cellSize * 2 + 2f, canvasHeight + 2f),
 strokeWidth = 12f,
 cap = StrokeCap.Round
 )
 drawLine(
 color = White,
 start = Offset(cellSize * 2, 0f),
 end = Offset(cellSize * 2, canvasHeight),
 strokeWidth = 8f,
 cap = StrokeCap.Round
 )

 drawLine(
 color = shadowColor,
 start = Offset(2f, cellSize + 2f),
 end = Offset(canvasWidth + 2f, cellSize + 2f),
 strokeWidth = 12f,
 cap = StrokeCap.Round
 )
 drawLine(
 color = White,
 start = Offset(0f, cellSize),
 end = Offset(canvasWidth, cellSize),
 strokeWidth = 8f,
 cap = StrokeCap.Round
 )
 
 drawLine(
 color = shadowColor,
 start = Offset(2f, cellSize * 2 + 2f),
