197| enabled = !bloc && !showInitialCards && !matchedCards[index],
198| onClick = {
199| if (!bloc && !visibleCards[index] && !matchedCards[index]) {
200| if (primer == null) {
201| primer = index
202| numPrimer = tauler[index]
203| visibleCards = visibleCards.toMutableList().apply { set(index, true) }
204| } else {
205| bloc = true
206| val numSegon = tauler[index]
207| visibleCards = visibleCards.toMutableList().apply { set(index, true) }
208|
209| if (numPrimer == numSegon) {
210| matchedCards = matchedCards.toMutableList().apply {
211| set(primer!!, true)
212| set(index, true)
213| }
214| puntuacio += 10
215| intents++
216| primer = null
217| bloc = false
218| } else {
219| puntuacio -= 2
220| intents++
221| val primerIndex = primer!!
222| coroutineScope.launch {
223| delay(1000)
224| visibleCards = visibleCards.toMutableList().apply {
225| set(primerIndex, false)
226| set(index, false)
227| }
228| primer = null
229| bloc = false
230| }
231| }
232| }
233| }
234| }
