 54|enum class CellState {
 55| EMPTY, O, X
 56|}
 57|
 58|@OptIn(ExperimentalMaterial3Api::class)
 59|@Composable
 60|fun TresEnRatllaScreen(onNavigateBack: () -> Unit = {}) {
 61| var board by remember { mutableStateOf(List(9) { CellState.EMPTY }) }
 62| var gameOver by remember { mutableStateOf(false) }
 63| var winner by remember { mutableStateOf<CellState?>(null) }
 64| var aiShouldMove by remember { mutableStateOf(false) }
 65|
 66| var wins by remember { mutableStateOf(0) }
 67| var losses by remember { mutableStateOf(0) }
 68| var ties by remember { mutableStateOf(0) }
 69|
 70| fun checkWinner(): CellState? {
 71| val winPatterns = listOf(
 72| listOf(0, 1, 2), listOf(3, 4, 5), listOf(6, 7, 8),
 73| listOf(0, 3, 6), listOf(1, 4, 7), listOf(2, 5, 8),
 74| listOf(0, 4, 8), listOf(2, 4, 6)
 75| )
 76|
 77| for (pattern in winPatterns) {
 78| val (a, b, c) = pattern
 79| if (board[a] != CellState.EMPTY &&
 80| board[a] == board[b] &&
 81| board[b] == board[c]
 82| ) {
 83| return board[a]
 84| }
 85| }
 86|
 87| if (board.none { it == CellState.EMPTY }) {
 88| return CellState.EMPTY
 89| }
 90|
 91| return null
 92| }
 93|
 94| fun handlePlayerMove(index: Int) {
 95| if (board[index] == CellState.EMPTY && !gameOver && !aiShouldMove) {
 96| board = board.toMutableList().apply { this[index] = CellState.O }
 97|
 98| val result = checkWinner()
 99| if (result != null) {
100| gameOver = true
101| winner = result
102| when (result) {
103| CellState.O -> wins++
104| CellState.X -> losses++
105| else -> ties++
106| }
107| } else {
108| aiShouldMove = true
109| }
110| }
111| }
112|
113| LaunchedEffect(aiShouldMove) {
114| if (aiShouldMove) {
115| delay(200)
116| board = aiMove(board)
117| val aiResult = checkWinner()
118| if (aiResult != null) {
119| gameOver = true
120| winner = aiResult
121| when (aiResult) {
122| CellState.O -> wins++
123| CellState.X -> losses++
124| else -> ties++
125| }
126| }
127| aiShouldMove = false
128| }
129| }
130|
131| fun resetGame() {
132| board = List(9) { CellState.EMPTY }
133| gameOver = false
134| winner = null
135| aiShouldMove = false
136| }
137|
138| fun resetScore() {
139| wins = 0
140| losses = 0
141| ties = 0
142| resetGame()
143| }
