437|fun aiMove(board: List<CellState>): List<CellState> {
438| val emptyIndices = board.indices.filter { board[it] == CellState.EMPTY }
439|
440| if (emptyIndices.isEmpty()) {
441| return board
442| }
443|
444| val randomIndex = emptyIndices[Random.nextInt(emptyIndices.size)]
445| return board.toMutableList().apply { this[randomIndex] = CellState.X }
446|}
